-- DRAFTS: a rehearsal file (every draft fact and row). Never apply it to production.
-- L04-K1-series.rollback.sql (run O1, lane L1; generated by apps/quiz/e2e/o1/L1/content-sql.mjs, do not edit by hand)
--
-- What:   undoes L04. Refused while a quiz, a bank row or a reader row uses one of the groups (roll back L08, L07 and L05 first).
-- o1-transaction: single (psql --single-transaction). Idempotent: a second run changes nothing.

set lock_timeout = '5s';
set client_min_messages = warning;
do $o1l$ begin
  if exists (select 1 from public.quizzes where group_id in (select id from public.groups where site_id = 'anime' and slug in ('apothecary-diaries', 'attack-on-titan', 'bleach', 'blue-lock', 'chainsaw-man', 'cowboy-bebop', 'dandadan', 'death-note', 'demon-slayer', 'dragon-ball', 'evangelion', 'frieren', 'fullmetal-alchemist', 'haikyu', 'hunter-x-hunter', 'jojo', 'jujutsu-kaisen', 'kagurabachi', 'kaiju-no-8', 'my-hero-academia', 'naruto', 'omniscient-readers-viewpoint', 'one-piece', 'one-punch-man', 'oshi-no-ko', 'sailor-moon', 'solo-leveling', 'spy-x-family', 'tower-of-god', 'vinland-saga', 'anime-mix')))
     or exists (select 1 from public.quiz_bank where group_id in (select id from public.groups where site_id = 'anime' and slug in ('apothecary-diaries', 'attack-on-titan', 'bleach', 'blue-lock', 'chainsaw-man', 'cowboy-bebop', 'dandadan', 'death-note', 'demon-slayer', 'dragon-ball', 'evangelion', 'frieren', 'fullmetal-alchemist', 'haikyu', 'hunter-x-hunter', 'jojo', 'jujutsu-kaisen', 'kagurabachi', 'kaiju-no-8', 'my-hero-academia', 'naruto', 'omniscient-readers-viewpoint', 'one-piece', 'one-punch-man', 'oshi-no-ko', 'sailor-moon', 'solo-leveling', 'spy-x-family', 'tower-of-god', 'vinland-saga', 'anime-mix')))
     or exists (select 1 from public.trivia where group_id in (select id from public.groups where site_id = 'anime' and slug in ('apothecary-diaries', 'attack-on-titan', 'bleach', 'blue-lock', 'chainsaw-man', 'cowboy-bebop', 'dandadan', 'death-note', 'demon-slayer', 'dragon-ball', 'evangelion', 'frieren', 'fullmetal-alchemist', 'haikyu', 'hunter-x-hunter', 'jojo', 'jujutsu-kaisen', 'kagurabachi', 'kaiju-no-8', 'my-hero-academia', 'naruto', 'omniscient-readers-viewpoint', 'one-piece', 'one-punch-man', 'oshi-no-ko', 'sailor-moon', 'solo-leveling', 'spy-x-family', 'tower-of-god', 'vinland-saga', 'anime-mix'))) then
    raise exception 'L04 rollback refused: quizzes, bank rows or trivia still use these groups; roll back L08, L07 and L05 first';
  end if;
end $o1l$;

